export function AnimatedAvatar({ name }) {
  const initials = name
    .split(' ')
    .map(p => p.charAt(0))
    .slice(0, 2)
    .join('')
    .toUpperCase();

  return (
    <div className="relative">
      <div className="conic-gradient animate-spin-slow" />
      <div className="bg-slate-900 rounded-full">
        {initials}
      </div>
      <div className="blur-xl animate-pulse-soft" />
    </div>
  );
}
